import React, {useEffect, useState} from 'react'
import NewsItem from './NewsItem'
import Spinner from './Spinner';
import PropTypes from 'prop-types'
import InfiniteScroll from "react-infinite-scroll-component";

const News = (props)=>{
    const [articles, setArticles] = useState([])
    const [loading, setLoading] = useState(true)
    const [page, setPage] = useState(1)
    const [totalResults, setTotalResults] = useState(0)
    
    const capitalizeFirstLetter = (string) => {
        return string.charAt(0).toUpperCase() + string.slice(1);
    } 

    const updateNews = async ()=> {
        props.setProgress(10);
        // Try a more general query to ensure we get results
        const url = `https://newsapi.org/v2/everything?q=${props.category}&domains=ndtv.com,hindustantimes.com,indianexpress.com,news18.com&language=en&apiKey=${props.apiKey}&page=${page}&pageSize=${props.pageSize}&sortBy=publishedAt`;
        
        console.log('Fetching URL:', url);
        setLoading(true)
        try {
            let data = await fetch(url);
            props.setProgress(30);
            let parsedData = await data.json()
            console.log('API Response:', parsedData); // Debug log
            
            if(parsedData.status === "ok" && parsedData.articles && parsedData.articles.length > 0) {
                props.setProgress(70);
                setArticles(parsedData.articles);
                setTotalResults(parsedData.totalResults);
            } else {
                console.error('API Response:', parsedData);
            }
        } catch (error) {
            console.error('Fetch Error:', error);
        }
        setLoading(false)
        props.setProgress(100);
    }

    useEffect(() => {
        console.log('Component mounted/updated');
        updateNews();
        // eslint-disable-next-line
    }, [])

    const fetchMoreData = async () => {   
        const url = `https://newsapi.org/v2/everything?q=${props.category}&domains=ndtv.com,hindustantimes.com,indianexpress.com,news18.com&language=en&apiKey=${props.apiKey}&page=${page+1}&pageSize=${props.pageSize}&sortBy=publishedAt`;
        setPage(page+1) 
        try {
            let data = await fetch(url);
            let parsedData = await data.json()
            if(parsedData.status === "ok" && parsedData.articles) {
                setArticles(articles.concat(parsedData.articles));
                setTotalResults(parsedData.totalResults);
            }
        } catch (error) {
            console.error('Fetch More Error:', error);
        }
    };
 
    return (
        <>
            <h1 className="text-center" style={{ margin: '35px 0px', marginTop: '90px' }}>
                NewsMonkey - Top {capitalizeFirstLetter(props.category)} Headlines
            </h1>
            {loading && <Spinner />}
            {!loading && articles.length === 0 && (
                <h2 className="text-center">No news available</h2>
            )}
            <InfiniteScroll
                dataLength={articles.length}
                next={fetchMoreData}
                hasMore={articles.length !== totalResults}
                loader={<Spinner/>}
            > 
                <div className="container">
                    <div className="row">
                        {articles.map((element, index) => {
                            return element ? (
                                <div className="col-md-4" key={index}>
                                    <NewsItem 
                                        title={element.title || ""}
                                        description={element.description || ""}
                                        imageUrl={element.urlToImage}
                                        newsUrl={element.url}
                                        author={element.author}
                                        date={element.publishedAt}
                                        source={element.source?.name || "Unknown"}
                                    />
                                </div>
                            ) : null;
                        })}
                    </div>
                </div> 
            </InfiniteScroll>
        </>
    )
}

News.defaultProps = {
    country: 'in',
    pageSize: 8,
    category: 'general',
}

News.propTypes = {
    country: PropTypes.string,
    pageSize: PropTypes.number,
    category: PropTypes.string,
}

export default News
